    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the regular {solid_name} with {edge_count} edges and {face_count} triangular faces. Assign to each edge a value from {0,1,2}, with arithmetic taken modulo 3. Determine how many edge-labelings satisfy the condition that, for every triangular face, the sum (mod 3) of the three edge values on that face is congruent to {face_sum}. Give your answer modulo {modulus}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a regular solid with triangular faces: tetrahedron, octahedron, icosahedron
solids = [
    # (name, E, F, dual_bipartite)
    ('tetrahedron', 6, 4, False),   # dual is tetrahedron (non-bipartite)
    ('octahedron', 12, 8, True),    # dual is cube (bipartite)
    ('icosahedron', 30, 20, False)  # dual is dodecahedron (non-bipartite)
]
# Bias towards harder instances (icosahedron) but keep variety
weights = [2, 3, 5]
total_w = sum(weights)
r = rng.randrange(total_w)
acc = 0
idx = 0
for i, w in enumerate(weights):
    acc += w
    if r < acc:
        idx = i
        break
name, E, F, dual_bip = solids[idx]

# Choose face_sum in {1,2}
face_sum = rng.choice([1, 2])

# Choose a modulus not divisible by 3 and reasonably large
def pick_mod():
    # Range chosen to avoid tiny moduli and trivial answers
    lo = 10**3 + 7
    hi = 10**6 + 123
    m = rng.randrange(lo, hi)
    # Ensure it's not divisible by 3 and at least 1000
    if m % 3 == 0:
        m += 1
        if m % 3 == 0:
            m += 1
    if m < 1000:
        m = 1009
    return m
modulus = pick_mod()

# Compute rank over GF(3) using dual bipartiteness heuristic:
# rank = F if dual not bipartite; else rank = F - 1
rank = F - (1 if dual_bip else 0)
exponent = E - rank

# Number of solutions is 3^(E - rank), solvable for any face_sum
# Answer modulo modulus
answer_mod = pow(3, exponent, modulus)

return {
    'solid_name': name,
    'edge_count': E,
    'face_count': F,
    'face_sum': face_sum,
    'modulus': modulus,
    # Store internal fields for potential debugging (not used by wrapper)
    '_dual_bipartite': dual_bip,
    '_rank': rank,
    '_exponent': exponent,
    '_answer_mod': answer_mod
}

    def verifier(assign):
# Validate presence of required fields
required = ['solid_name', 'edge_count', 'face_count', 'face_sum', 'modulus']
for key in required:
    if key not in assign:
        # Missing field
        return (False, None)
name = assign['solid_name']
E = assign['edge_count']
F = assign['face_count']
s = assign['face_sum']
mod = assign['modulus']

# Validate domain constraints
solids = {
    'tetrahedron': (6, 4, False),   # (E, F, dual_bipartite)
    'octahedron': (12, 8, True),
    'icosahedron': (30, 20, False)
    }
if name not in solids:
    # Unknown solid
    return (False, None)
E0, F0, dual_bip = solids[name]
if E != E0 or F != F0:
    # Inconsistent counts for the named solid
    return (False, None)
if s not in (1, 2):
    # Only {1,2} allowed to avoid the trivial all-equal solution class
    return (False, None)
if not isinstance(mod, int) or mod < 2:
    return (False, None)
if mod % 3 == 0 or mod < 1000:
    # Avoid trivial moduli and ensure difficulty
    return (False, None)

# Linear-algebraic rank over GF(3): rank = F - 1 if dual is bipartite; else rank = F
rank = F - (1 if dual_bip else 0)

# Surjectivity and solvability check:
# If rank == F, A is surjective, so any RHS (including constant vector s) is solvable.
# If rank == F - 1 (octahedron case), the left-nullspace is 1D spanned by a bipartition vector y with sum zero,
# hence y·(s*1) = s*sum(y) = 0, so the system is still consistent.

exponent = E - rank
# Number of solutions over GF(3) equals 3^(E - rank)
ans = pow(3, exponent, mod)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

